import React, { useEffect, useState } from 'react';
import { Box, Typography, Card, CardContent, Button, Stack, AppBar, useTheme } from '@mui/material';
import MinimalAppBar from '../../Component/MinimalAppBar';
import callApi from '../../Services/callApi';
import { AnimatePresence, motion } from 'framer-motion';
import { Outlet, useNavigate } from 'react-router-dom';
const LoanScreen = () => {
  const navigate = useNavigate();
  const [data, setData] = useState<any[]>([]);
  const [item, setItem] = useState<any>();
  const theme = useTheme();
  const [currentIndex, setCurrentIndex] = useState(0);
  useEffect(() => {
    onLoad();
  }, [])

  useEffect(() => {
    setItem(data[currentIndex]);
  }, [currentIndex])

  const onLoad = async () => {
    var res = await callApi.get('/personalloan/myloan');
    if (res.data?.success) {
      setItem(res.data?.data[currentIndex]);
      setData(res.data?.data);
    }
  }


  const handleNext = () => {
    setCurrentIndex((prev) => (prev < data.length - 1 ? prev + 1 : prev));
  };

  const handlePrev = () => {
    setCurrentIndex((prev) => (prev > 0 ? prev - 1 : prev));
  };



  return (
    <>
      <MinimalAppBar onBack={() => window.history.back} title="สินเชื่อของฉัน"></MinimalAppBar>
      <AnimatePresence mode="wait">
        {item && <motion.div
          key={item.id}

          initial={{ opacity: 0, y: 20 }}
          animate={{ opacity: 1, y: 0 }}
          exit={{ opacity: 0, y: -20 }}
          transition={{
            duration: 0.6,
            ease: [0.25, 0.8, 0.25, 1], // ease-in-out แบบนุ่ม
          }}

        >
          <Card sx={{ width: '100%' }}>
            <CardContent
              sx={{
                // background: 'linear-gradient(135deg, #c8d60cff 0%, #b915b1ff 50%, #d80adfff 100%)',
                padding: 4,
                borderRadius: 0,
                color: '#FFFFFF',
                fontFamily: 'Prompt, sans-serif',
              }}
            >
              <Box p={0} bgcolor="background.primary">
                {/* สรุปสินเชื่อ */}
                {item && <Box sx={{ px: { xs: 2, sm: 4 }, py: 2 }}>
                  {/* การ์ดเดียวตาม index */}
                  <Box sx={{ mb: 4 }}>
                    <Card sx={{ width: '100%' }}>
                      <CardContent
                        sx={{
                          background: theme.palette.background.default,
                          padding: 4,
                          borderRadius: 0,
                          color: '#FFFFFF',
                          fontFamily: 'Prompt, sans-serif',
                        }}
                      >
                        <Stack spacing={2}>
                          <Typography variant="subtitle1">
                            เลขที่สัญญา : {item.id}
                          </Typography>
                          <Typography variant="subtitle1">ยอดคงเหลือ</Typography>
                          <Typography variant="h4">
                            ฿{item.loanAmount.toLocaleString()}
                          </Typography>

                          <Box
                            sx={{
                              display: 'flex',
                              flexDirection: { xs: 'column', sm: 'row' },
                              justifyContent: 'space-between',
                              gap: 2,
                            }}
                          >
                            <Box>
                              <Typography variant="subtitle2">ยอดผ่อน/เดือน</Typography>
                              <Typography>
                                ฿{item.installmentAmount.toLocaleString()}
                              </Typography>
                            </Box>
                          </Box>
                        </Stack>
                      </CardContent>
                    </Card>

                    {/* เมนูการดำเนินการ */}
                    <Stack
                      direction={{ xs: 'column', sm: 'row' }}
                      spacing={2}
                      sx={{ mt: 2 }}
                    >
                      <Button fullWidth variant="outlined" color="primary" 
                      onClick={()=>navigate('LoanDetail',{state:item})}
                      >
                        ดูรายละเอียดสัญญา
                      </Button>
                    </Stack>
                  </Box>

                  {/* ปุ่มเลื่อนการ์ด */}
                  <Stack direction="row" spacing={2} justifyContent="center">
                    <Button
                      fullWidth
                      variant="contained"
                      onClick={handlePrev}
                      disabled={currentIndex === 0}
                    >
                      ก่อนหน้า
                    </Button>
                    <Button
                      fullWidth
                      variant="contained"
                      onClick={handleNext}
                      disabled={currentIndex === data.length - 1}
                    >
                      ถัดไป
                    </Button>
                  </Stack>
                </Box>}

              </Box>
              
            </CardContent>
          </Card>
           <Outlet />
        </motion.div>}
      </AnimatePresence>


    </>
  );
};

export default LoanScreen;
